from pathlib import Path
exec(Path('tmp/pdfs/tutorial-liraa-20261020/build.py').read_text().split('\nS=[]')[0])
class UpdatesCanvas(NumberedCanvas):
 _doc_title='Relatório de atualizações'
S=[]
S += [p('Atualizações de vigilância','title'),p('LIRAa, mapa de risco e compartilhamento de ações realizadas<br/>Relatório funcional - posição do código local em 20/10/2026','subtitle')]
S += [p('1. Finalidade e organização','h'),p('Este relatório reúne as funcionalidades implementadas para organizar o levantamento entomológico, consultar resultados geográficos e divulgar ações autorizadas à sociedade. A demonstração usa o mesmo fluxo de gravação e consulta, com dados fictícios identificados e separados dos dados autorizados.')]
S += [note('Escopo da entrega','A presença de uma funcionalidade no código não confirma sua disponibilidade em produção nem substitui a validação técnica municipal ou o aceite da prova de conceito. Configuração, migrações, permissões e testes no ambiente publicado devem ser conferidos.')]
S += [p('2. Planejamento territorial do LIRAa','h'),table([['Atualização','Comportamento disponível'],['Cadastro territorial','Cadastro manual e importação CSV de quarteirões, bairros, áreas, quantidade de imóveis e referência do cadastro municipal.'],['Delimitação no mapa','Busca de localização, desenho por pontos, ajuste, consulta e remoção do contorno. A alteração depende de confirmação e salvamento do quarteirão.'],['Levantamentos','Criação de rascunho com código, nome, período, responsável técnico e referência do plano amostral; edição antes da liberação.'],['Estratos e metas','Cadastro de estratos, população de imóveis, metas e critério de delimitação; seleção de quarteirões manualmente ou por CSV da amostra.'],['Distribuição do trabalho','Atribuição de quarteirões a contas de agentes da mesma prefeitura. Validação das metas antes da liberação para campo.'],['Ciclo de execução','Rascunho, liberação e encerramento; acompanhamento de execução, pendências e histórico do planejamento.']],[132,363.28])]
S += [Spacer(1,8),p('O desenho delimita o território, mas não conta imóveis, sorteia a amostra ou define sozinho a metodologia. A coordenação informa e revisa esses elementos. Os contornos usados na amostra ficam preservados no planejamento.','small')]
S += [PageBreak(),p('Coleta, armazenamento e índices','title'),p('Registros de campo, cargas de arquivos e consolidação','subtitle')]
S += [p('3. Coleta pelos agentes e pela coordenação','h'),p('Foi criado o perfil <b>Agente de Endemias</b>, com acesso aos quarteirões atribuídos em levantamentos liberados. O agente informa imóvel, visita, data, situação, resultado para Aedes, recipientes positivos e localização opcional. A coordenação também registra visitas pelo quarteirão ou pela tela de campo.')]
S += [p('Os formulários seguem duas etapas: <b>revisar</b> e <b>confirmar</b>. Depois da confirmação, a visita fica disponível para os resultados e para a coordenação, sem uma segunda aprovação obrigatória. A consulta de OS permanece opcional como auxílio de endereço; não comprova inspeção LIRAa nem positividade.')]
S += [p('4. Importação CSV e persistência','h'),p('As visitas podem ser enviadas em CSV UTF-8, validadas e confirmadas em lote. A tela distingue <b>VALIDADO</b>, <b>REJEITADO</b> e <b>CONCLUÍDO</b>, apresenta erros e preserva a identificação da carga, autoria, origem e hash do arquivo. Registros existentes são conferidos para evitar duplicação; conflitos impedem a confirmação da carga.'),p('Planejamento, visitas e vínculos são persistidos no banco configurado pela aplicação. Demonstração e dados autorizados ficam separados. A confirmação da carga, e não apenas sua validação, alimenta o consolidado.')]
S += [note('Limitação da importação planejada','A importação genérica de visitas não faz o vínculo automático com o quarteirão de um planejamento cadastrado. Para comprovar o fluxo coordenação → agente → acompanhamento das metas, abra o registro pelo quarteirão do levantamento liberado.')]
S += [p('5. Resultados e indicadores','h'),table([['Resultado','Regra do sistema'],['IIP','100 × imóveis positivos ÷ imóveis inspecionados, por levantamento, estrato e área.'],['Índice de Breteau','100 × recipientes positivos ÷ imóveis inspecionados, quando as contagens permitem calcular.'],['ITR','Distribuição percentual dos recipientes positivos pelas categorias A1, A2, B, C, D1, D2 e E, quando há denominador.'],['Pendências e recortes','Fechados, recusados e não inspecionados não entram no denominador do IIP. Focal é mantido como atividade distinta. Filtros por período e território delimitam o recorte exibido.']],[132,363.28])]
S += [Spacer(1,8),p('Contagens ausentes de recipientes não são tratadas como zero. O sistema informa quando não há base suficiente para o índice. Os resultados permanecem sujeitos à conferência técnica do levantamento.','small')]
S += [PageBreak(),p('Mapas e integração das informações','title'),p('Geografia real, fontes separadas e consulta pública','subtitle')]
S += [p('6. Mapa dos levantamentos confirmados','h'),p('O mapa passou a consultar os registros efetivamente confirmados, inclusive os recebidos por CSV. A apresentação utiliza a malha municipal do IBGE disponível para Pernambuco e contornos cadastrados no planejamento, em vez de representar os municípios por quadrados fictícios.'),p('Os pontos dependem das coordenadas das visitas. As áreas com IIP dependem de contornos preservados no plano e da correspondência dos códigos do levantamento, estrato e área. Quando só parte dos quarteirões possui desenho, o mapa informa essa limitação. Os índices continuam disponíveis em tabela mesmo sem contorno.')]
S += [p('7. Resultados com SINAN e tratamento focal','h'),p('O painel reúne indicadores e camadas mantendo a origem de cada informação: <b>LIRAa</b>, <b>tratamento focal</b> e <b>SINAN selecionado</b>. A comparação usa prefeitura vinculada ao código IBGE, doença, ano, lote e recorte epidemiológico, conforme os filtros disponíveis.'),p('CSV SINAN com coordenadas pode fornecer pontos individuais à área restrita. A API pública importada fornece dados municipais sem coordenadas individuais: seus totais podem ser comparados, mas não são transformados em endereços de pacientes. Uma consulta à API não salva automaticamente um lote.')]
S += [p('8. Análise histórica de casos','h'),p('A opção <b>Histórico de casos - avançado</b> recebe GeoJSON territorial e CSV agregado de casos prováveis de dengue por área e ano. Oferece análise exploratória Gi*, recorrência, mapas, tabelas e análises salvas. A avaliação exige cobertura compatível, pelo menos cinco anos consecutivos e outras condições verificadas pelo sistema. Dados insuficientes geram avisos, sem classificação artificial.')]
S += [p('9. Mapa no Portal do Cidadão','h'),p('A consulta pública apresenta filtros de região e município, incluindo os municípios do CONDOMAR, além dos recortes de fonte e período disponíveis. O mapa utiliza os mesmos registros persistidos, com uma representação pública agregada de LIRAa, atividade focal e SINAN.'),p('A seleção de município ou modo de dados limpa o levantamento anterior para evitar filtros incompatíveis. A visão pública não expõe pontos individuais, nomes, endereços, fotos de relatos ou identificadores de pacientes.')]
S += [note('Como interpretar as cores e as fontes','O IIP descreve a infestação na amostra e não confirma casos de doença. Sua escala numérica não deve ser apresentada como diagnóstico automático de epidemia. A análise histórica Gi* é outra fonte, com método e requisitos próprios. OS e relatos de suspeita não equivalem a casos confirmados do SINAN.')]
S += [PageBreak(),p('Compartilhamento e mídias','title'),p('Publicação autorizada de ações realizadas','subtitle')]
S += [p('10. Preparação e publicação das ações','h'),p('O módulo <b>Ações realizadas</b> permite cadastrar título, tipo da atividade, bairro ou área, período e descrição pública, com fotos ou vídeos selecionados. Pode ser iniciado a partir de uma ação ou referência operacional permitida, mas a publicação exige preparação e revisão próprias.')]
S += [table([['Etapa','Funcionamento'],['Rascunho','Usuário autorizado prepara o texto e adiciona as mídias que serão divulgadas.'],['Revisão','O conteúdo é enviado para revisão. A prévia privada permite conferir o texto e as mídias antes da divulgação.'],['Publicação','Usuário com permissão confirma a autorização e publica uma versão aprovada no Portal do Cidadão.'],['Alteração e retirada','Alterações no rascunho não substituem automaticamente a versão pública já aprovada. É possível publicar nova versão ou retirar a publicação. O histórico registra as transições.']],[132,363.28])]
S += [Spacer(1,9),p('11. Quem compartilha e como','h'),p('COVISA, administração municipal ou outros usuários autorizados preparam e publicam conforme suas permissões. O perfil de agente não recebe acesso editorial automaticamente. Depois de publicada, a página oferece <b>Copiar link</b>, <b>WhatsApp</b>, <b>Facebook</b> e compartilhamento nativo quando suportado pelo navegador.'),p('O cidadão ou integrante da equipe inicia o compartilhamento. O sistema compartilha o endereço público da ação e não faz postagem automática nas contas das redes sociais.')]
S += [p('12. Salvamento e proteção das fotos','h'),p('O arquivo é enviado ao <b>Skybox</b> quando as credenciais estão configuradas; caso contrário, é salvo na pasta local de uploads. O banco guarda a referência do arquivo, legenda, tamanho, hash e vínculo com a ação. Imagens são convertidas em cópias JPEG sem metadados EXIF/GPS e redimensionadas para divulgação.'),p('São aceitas imagens JPG, PNG e WebP de até 10 MiB; vídeos MP4 de até 50 MiB dependem de FFmpeg no servidor. Cada publicação admite até cinco mídias selecionadas. O acesso público é limitado às mídias da versão aprovada.')]
S += [note('Cuidados operacionais','Remover metadados não apaga rostos, placas ou dados visíveis na imagem. O responsável deve revisar o conteúdo antes de publicar. Em hospedagem com disco efêmero, o armazenamento local precisa de persistência ou de um serviço externo para conservar as mídias após deploys.')]
S += [PageBreak(),p('Interface, ativação e conferência','title'),p('Condições de uso e roteiro de validação funcional','subtitle')]
S += [p('13. Organização das telas','h'),p('A navegação interna do LIRAa foi organizada por tarefa: <b>Planejar → Registrar visitas → Ver resultados</b>. Os cards da Central de Vigilância foram mantidos. A listagem de levantamentos é a entrada do planejamento, com criação de rascunho sob demanda e cadastro territorial acessível por ação própria.'),p('No SINAN, as tarefas passaram a ser <b>Consultar dados</b> e <b>Importar dados</b>, com filtros de município, doença e ano visíveis e escolha da origem CSV/API. Formulários, histórico e opções técnicas foram reorganizados. O bloco visível de colunas e regras do layout foi retirado da importação de visitas; as validações continuam ativas.')]
S += [p('14. Configuração e implantação','h'),table([['Item','Condição para funcionamento'],['Banco de dados','O ambiente deve ter as migrações correspondentes ao código publicado. As mudanças visuais, isoladamente, não criam tabelas. A migração a73e5c9b204f cria as três tabelas de ações públicas.'],['Ações realizadas','ACOES_PUBLICAS_ENABLED=1 e permissões adequadas. Tabelas do módulo precisam estar disponíveis.'],['SINAN','SINAN_ENABLED e SINAN_IMPORT_ENABLED ativos; SINAN_STORAGE_BACKEND=database para usar o banco principal configurado.'],['Vínculo municipal','VIGILANCIA_MUNICIPIOS_IBGE relaciona IDs internos das prefeituras e códigos IBGE. Cadastro de prefeitura e código IBGE não são a mesma chave.'],['Mapas e arquivos','Google Maps requer chave, APIs e domínio autorizados nas telas que usam esse serviço. Mídias requerem Skybox configurado ou disco local persistente; MP4 requer FFmpeg.']],[132,363.28])]
S += [Spacer(1,8),p('15. Roteiro para conferir na prova de conceito','h'),p('1. Selecionar Pesqueira e demonstração nas telas envolvidas.<br/>2. Cadastrar território e salvar um contorno real no mapa.<br/>3. Criar a amostra, atribuir agente e liberar o levantamento.<br/>4. Registrar visita pelo agente, revisar e confirmar.<br/>5. Conferir metas, pendências, IIP, resultados e camadas do mapa.<br/>6. Abrir o Portal do Cidadão e conferir o recorte público agregado.<br/>7. Cadastrar ação fictícia com foto, revisar e publicar.<br/>8. Abrir o link público e testar os controles de compartilhamento.')]
output=ROOT/'output/pdf/IJA-System-Atualizacoes-LIRAa-Mapa-de-Risco-e-Compartilhamento.pdf'
build(output,S,'Atualizações - LIRAa, mapa de risco e compartilhamento',UpdatesCanvas)
print(output)
